import { Component, createSignal, For, Setter } from "solid-js";

import { ArrowButton } from "#core/ui-next/components/arrow-button.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { BoundBoolean, BoundString } from "#core/ui-next/sandbox/components-browser/components/bound-property.jsx";
import { createArraySignal } from "#core/ui-next/utilities/solid-utilities.js";

export const ArrowButtonExample: Component = () => {
	const [audioGroup, setAudioGroup] = createSignal<string>();
	const [audioActivate, setAudioActivate] = createSignal<string>();
	const [audioPress, setAudioPress] = createSignal<string>();
	const [audioError, setAudioError] = createSignal<string>();
	const [audioFocus, setAudioFocus] = createSignal<string>();
	const [disabled, setDisabled] = createSignal(false);
	const [disableFocus, setDisableFocus] = createSignal(false);
	const [hotkeyAction, setHotkeyAction] = createSignal<string>();
	const [navTrayText, setNavtrayText] = createSignal<string>();
	const [onActivateMessage, setOnActivateMessage] = createSignal("onActivate");
	const [onBlurMessage, setOnBlurMessage] = createSignal("onBlur");
	const [onFocusMessage, setOnFocusMessage] = createSignal("onFocus");
	const [right, setRight] = createSignal(false);

	const [messages, useMessages] = createArraySignal<string>(["Message Log"]);

	return (
		<div class="flex flex-row flex-auto mx-4">
			<ScrollArea class="w-1\/3 m-2 p-2 border border-secondary-3">
				<BoundBoolean
					name="isRight"
					signal={[right, setRight as Setter<boolean | undefined>]}
				/>
				<BoundBoolean
					name="disabled"
					signal={[disabled, setDisabled as Setter<boolean | undefined>]}
				/>
				<BoundBoolean
					name="disableFocus"
					signal={[disableFocus, setDisableFocus as Setter<boolean | undefined>]}
				/>
				<BoundString
					name="hotkeyAction"
					signal={[hotkeyAction, setHotkeyAction]}
				/>
				<BoundString
					name="navTrayText"
					signal={[navTrayText, setNavtrayText]}
				/>
				<BoundString
					name="audio.group"
					signal={[audioGroup, setAudioGroup]}
				/>
				<BoundString
					name="audio.onActivate"
					signal={[audioActivate, setAudioActivate]}
				/>
				<BoundString
					name="audio.onPress"
					signal={[audioPress, setAudioPress]}
				/>
				<BoundString
					name="audio.onError"
					signal={[audioError, setAudioError]}
				/>
				<BoundString
					name="audio.onFocus"
					signal={[audioFocus, setAudioFocus]}
				/>
				<BoundString
					name="onActivate Message"
					signal={[onActivateMessage, setOnActivateMessage as Setter<string | undefined>]}
				/>
				<BoundString
					name="onFocus Message"
					signal={[onFocusMessage, setOnFocusMessage as Setter<string | undefined>]}
				/>
				<BoundString
					name="onBlur Message"
					signal={[onBlurMessage, setOnBlurMessage as Setter<string | undefined>]}
				/>
			</ScrollArea>
			<div class="w-1\/3 m-2 p-2 border border-secondary-3 flex flex-col justify-center items-center">
				<ArrowButton
					class="border-1"
					name="ExampleActivatable"
					audio={{
						group: audioGroup(),
						onActivate: audioActivate(),
						onPress: audioPress(),
						onError: audioError(),
						onFocus: audioFocus(),
					}}
					right={right()}
					disabled={disabled()}
					disableFocus={disableFocus()}
					hotkeyAction={hotkeyAction()}
					navTrayText={navTrayText()}
					onActivate={() => useMessages((m) => m.push(onActivateMessage()))}
					onBlur={() => useMessages((m) => m.push(onBlurMessage()))}
					onFocus={() => useMessages((m) => m.push(onFocusMessage()))}
				/>
			</div>
			<div class="w-1\/3 m-2 p-2 bg-accent-6 border border-secondary-3">
				<Button
					class="mb-2"
					onActivate={() => useMessages((msgs) => (msgs.length = 0))}
				>
					Clear Log
				</Button>
				<ScrollArea class="flex-auto">
					<For each={messages()}>{(message) => <div>{message}</div>}</For>
				</ScrollArea>
				<div class="w-64 h-16 border">
					<nav-tray />
				</div>
			</div>
		</div>
	);
};
